<?php $start = $total ? (($filters['page'] - 1) * $filters['per_page']) + 1 : 0; $end = min($filters['page'] * $filters['per_page'], $total); $vehicleTypes = ['Motorcycle','Car','Van','SUV','Three Wheeler','Truck','Other']; ?>
<div class="customer-heading vehicle-heading"><div><div class="breadcrumb-line">Dashboard <span>›</span> Vehicles <span>›</span> <b>All Vehicles</b></div><h1>All Vehicles</h1></div><a class="btn btn-danger customer-add-button" href="#vehicle-form">＋ Add Vehicle</a></div>
<div class="admin-panel vehicle-list-panel"><form class="vehicle-filter-bar" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="vehicles"><input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search by Vehicle No, Customer or Mobile..."><select class="form-select" name="type"><option value="">All Vehicle Types</option><?php foreach ($vehicleTypes as $type): ?><option value="<?= e($type) ?>" <?= $filters['type'] === $type ? 'selected' : '' ?>><?= e($type) ?></option><?php endforeach; ?></select><select class="form-select" name="status"><option value="">All Status</option><option value="active" <?= $filters['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $filters['status'] === 'inactive' ? 'selected' : '' ?>>Inactive</option></select><button class="btn btn-danger" type="submit">Search</button><a class="btn btn-light" href="index.php?page=admin&amp;section=vehicles">Clear</a></form><div class="table-responsive"><table class="table admin-table vehicle-table"><thead><tr><th>#</th><th>Vehicle No</th><th>Customer Name</th><th>Mobile</th><th>Vehicle Type</th><th>Make / Model</th><th>Year</th><th>Mileage (KM)</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="10" class="empty-table">No vehicles found. Add a vehicle to begin.</td></tr><?php else: ?><?php foreach ($rows as $index => $row): ?><tr><td><?= $start + $index ?></td><td><strong><?= e($row['vehicle_number']) ?></strong></td><td><?= e($row['customer_name']) ?></td><td><?= e($row['customer_contact']) ?></td><td><span class="type-badge type-individual"><?= e($row['vehicle_type']) ?></span></td><td><?= e(trim(($row['make'] ?? '') . ' ' . $row['model'])) ?></td><td><?= e((string) ($row['year'] ?: '-')) ?></td><td><?= e(number_format((float) $row['current_mileage'], 0)) ?></td><td><span class="status-badge status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><a class="vehicle-action" href="index.php?page=admin&amp;section=customers-view&amp;id=<?= (int) $row['customer_id'] ?>" aria-label="View customer">◉</a></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div><div class="customer-table-footer"><span>Showing <?= $start ?> to <?= $end ?> of <?= $total ?> vehicles</span><?php if ($pages > 1): ?><nav aria-label="Vehicle pagination"><ul class="pagination pagination-sm mb-0"><li class="page-item <?= $filters['page'] <= 1 ? 'disabled' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=vehicles&amp;p=<?= max(1, $filters['page'] - 1) ?>&amp;per_page=<?= $filters['per_page'] ?>">Prev</a></li><?php for ($number = 1; $number <= $pages; $number++): ?><li class="page-item <?= $number === $filters['page'] ? 'active' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=vehicles&amp;p=<?= $number ?>&amp;per_page=<?= $filters['per_page'] ?>"><?= $number ?></a></li><?php endfor; ?><li class="page-item <?= $filters['page'] >= $pages ? 'disabled' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=vehicles&amp;p=<?= min($pages, $filters['page'] + 1) ?>&amp;per_page=<?= $filters['per_page'] ?>">Next</a></li></ul></nav><?php endif; ?></div></div>
<div class="admin-panel vehicle-entry-panel" id="vehicle-form"><div class="customer-list-heading"><h2>Add Vehicle</h2><a class="btn btn-light" href="index.php?page=admin&amp;section=vehicles">← Back to Vehicles</a></div><?php if ($errors): ?><div class="alert alert-danger"><?php foreach ($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="index.php?page=admin&amp;section=vehicles-add"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-4 col-xl"><label class="form-label">Customer <span>*</span></label><select class="form-select" name="customer_id" required><option value="">Select Customer</option><?php foreach ($customers as $customer): ?><option value="<?= (int) $customer['id'] ?>" <?= (int) $input['customer_id'] === (int) $customer['id'] ? 'selected' : '' ?>><?= e($customer['name'] . ' (' . $customer['contact_number'] . ')') ?></option><?php endforeach; ?></select><small class="vehicle-form-link">+ Add New Customer</small></div><div class="col-md-4 col-xl"><label class="form-label">Vehicle No <span>*</span></label><input class="form-control" name="vehicle_number" value="<?= e($input['vehicle_number']) ?>" placeholder="Enter vehicle number" required maxlength="40"></div><div class="col-md-4 col-xl"><label class="form-label">Vehicle Type <span>*</span></label><select class="form-select" name="vehicle_type" required><option value="">Select vehicle type</option><?php foreach ($vehicleTypes as $type): ?><option value="<?= e($type) ?>" <?= $input['vehicle_type'] === $type ? 'selected' : '' ?>><?= e($type) ?></option><?php endforeach; ?></select></div><div class="col-md-4 col-xl"><label class="form-label">Make / Brand</label><input class="form-control" name="make" value="<?= e($input['make']) ?>" placeholder="Enter make or brand" maxlength="100"></div><div class="col-md-4 col-xl"><label class="form-label">Model <span>*</span></label><input class="form-control" name="model" value="<?= e($input['model']) ?>" placeholder="Enter model" required maxlength="100"></div><div class="col-md-4 col-xl"><label class="form-label">Year</label><select class="form-select" name="year"><option value="">Select year</option><?php for ($year = (int) date('Y') + 1; $year >= 1950; $year--): ?><option value="<?= $year ?>" <?= (string) $input['year'] === (string) $year ? 'selected' : '' ?>><?= $year ?></option><?php endfor; ?></select></div><div class="col-md-4 col-xl"><label class="form-label">Colour</label><input class="form-control" name="colour" value="<?= e($input['colour']) ?>" placeholder="Enter colour" maxlength="60"></div><div class="col-md-4 col-xl"><label class="form-label">Engine Number</label><input class="form-control" name="engine_number" value="<?= e($input['engine_number']) ?>" placeholder="Enter engine number" maxlength="100"></div><div class="col-md-4 col-xl"><label class="form-label">Chassis Number</label><input class="form-control" name="chassis_number" value="<?= e($input['chassis_number']) ?>" placeholder="Enter chassis number" maxlength="100"></div><div class="col-md-4 col-xl"><label class="form-label">Fuel Type</label><select class="form-select" name="fuel_type"><option value="">Select fuel type</option><?php foreach (['Petrol','Diesel','Hybrid','Electric','Other'] as $fuel): ?><option value="<?= e($fuel) ?>" <?= $input['fuel_type'] === $fuel ? 'selected' : '' ?>><?= e($fuel) ?></option><?php endforeach; ?></select></div><div class="col-md-4 col-xl"><label class="form-label">Current Mileage (KM) <span>*</span></label><div class="input-group"><input class="form-control" type="number" min="0" step="0.01" name="current_mileage" value="<?= e($input['current_mileage']) ?>" placeholder="Enter current mileage" required><span class="input-group-text">km</span></div></div><div class="col-12"><label class="form-label">Notes (Optional)</label><textarea class="form-control" name="notes" rows="2" placeholder="Enter any additional notes..."><?= e($input['notes']) ?></textarea></div></div><div class="customer-form-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=vehicles">Cancel</a><button class="btn btn-danger" type="reset">Reset</button><button class="btn btn-danger" type="submit">Save Vehicle</button></div></form></div>
